        // Check if already adjacent
        if (abs($a[0] - $b[0]) + abs($a[1] - $b[1]) == 1) {
            $possible[] = [$a, $b];
        }
        // Generate all adjacent pairs
        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $m; $j++) {
                // Check right neighbor
                if ($j + 1 < $m) {
                    $possible[] = [[$i, $j], [$i, $j + 1]];
                }
                // Check down neighbor
                if ($i + 1 < $n) {
                    $possible[] = [[$i, $j], [$i + 1, $j]];
                }
            }
        }
        // Remove duplicates
        $unique = [];
        foreach ($possible as $p) {
            $key = serialize($p);
            if (!isset($unique[$key])) {
                $unique[$key] = $p;
            }
        }
        $targets[$idx] = array_values($unique);
