    // Backtracking to find minimal moves
    $minMoves = PHP_INT_MAX;
    $used = array_fill(0, $n, array_fill(0, $m, false));

    function backtrack($pairIdx, $currentMoves, &$minMoves, &$used, $targets, $pairList) {
        if ($pairIdx === count($pairList)) {
            if ($currentMoves < $minMoves) {
                $minMoves = $currentMoves;
