            if ($i > 0) $neighbors[] = [($i-1), $j];
            if ($i < $n-1) $neighbors[] = [($i+1), $j];
            if ($j > 0) $neighbors[] = [$i, ($j-1)];
            if ($j < $m-1) $neighbors[] = [$i, ($j+1)];
            $adj[$i][$j] = $neighbors;
        }
    }

    $minMoves = PHP_INT_MAX;

    $pairCount = count($pairList);
    $used = array_fill(0, $n, array_fill(0, $m, false));

    function backtrack($index, $used, $adj, $pairList, &$minMoves) {
        if ($index === count($pairList)) {
            $moves = 0;
            foreach ($pairList as $pair) {
                $p1 = $pair[0];
                $p2 = $pair[1];
                $val = $GLOBALS['grid'][$p1[0]][$p1[1]];
                $otherVal = $GLOBALS['grid'][$p2[0]][$p2[1]];
                if ($val !== $otherVal) {
                    $moves += 1;
                }
            }
            if ($moves < $minMoves) {
                $minMoves = $moves;
            }
            return;
        }

        $pair = $pairList[$index];
        $p1 = $pair[0];
        $p2 = $pair[1];

        if ($used[$p1[0]][$p1[1]] || $used[$p2[0]][$p2[1]]) {
            return;
        }

        $used[$p1[0]][$p1[1]] = true;
        $used[$p2[0]][$p2[1]] = true;

        backtrack($index + 1, $used, $adj, $pairList, $minMoves);

        $used[$p1[0]][$p1[1]] = false;
        $used[$p2[0]][$p2[1]] = false;
    }

    backtrack(0, $used, $adj, $pairList, $minMoves);

    echo $minMoves . "\n";
}

main();
