<?php
function main() {
    $line = trim(fgets(STDIN));
    list($n, $m) = array_map('intval', explode(' ', $line));
    $grid = [];
    for ($i = 0; $i < $n; $i++) {
        $row = array_map('intval', explode(' ', trim(fgets(STDIN))));
        $grid[] = $row;
    }
    $total = $n * $m;
    $pairs = $total / 2;
    $positions = [];
    for ($i = 0; $i < $n; $i++) {
        for ($j = 0; $j < $m; $j++) {
            $val = $grid[$i][$j];
            if (!isset($positions[$val])) {
                $positions[$val] = [];
            }
            $positions[$val][] = [$i, $j];
        }
    }
    $pairList = array_values($positions);
    $numPairs = count($pairList);
    $adj = array_fill(0, $numPairs, []);
    for ($i = 0; $i < $numPairs; $i++) {
        for ($j = $i + 1; $j < $numPairs; $j++) {
            $a = $pairList[$i][0];
            $b = $pairList[$i][1];
            $c = $pairList[$j][0];
            $d = $pairList[$j][1];
            $dist1 = abs($a[0] - $c[0]) + abs($a[1] - $c[1]);
            $dist2 = abs($b[0] - $d[0]) + abs($b[1] - $d[1]);
            $dist3 = abs($a[0] - $d[0]) + abs($a[1] - $d[1]);
            $dist4 = abs($b[0] - $c[0]) + abs($b[1] - $c[1]);
            $cost1 = $dist1 + $dist2;
            $cost2 = $dist3 + $dist4;
            $minCost = min($cost1, $cost2);
            $adj[$i][$j] = $minCost;
            $adj[$j][$i] = $minCost;
        }
    }
    $INF = PHP_INT_MAX;
    $dp = array_fill(0, 1 << $numPairs, array_fill(0, $numPairs, $INF));
    for ($i = 0; $i < $numPairs; $i++) {
        $dp[1 << $i][$i] = 0;
    }
    for ($mask = 0; $mask < (1 << $numPairs); $mask++) {
        for ($last = 0; $last < $numPairs; $last++) {
            if ($dp[$mask][$last] === $INF) continue;
            for ($next = 0; $next < $numPairs; $next++) {
                if ($mask & (1 << $next)) continue;
                $newMask = $mask | (1 << $next);
                $newCost = $dp[$mask][$last] + $adj[$last][$next];
                if ($newCost < $dp[$newMask][$next]) {
                    $dp[$newMask][$next] = $newCost;
                }
            }
        }
    }
    $fullMask = (1 << $numPairs) - 1;
    $minCost = $INF;
    for ($i = 0; $i < $numPairs; $i++) {
        if ($dp[$fullMask][$i] < $minCost) {
            $minCost = $dp[$fullMask][$i];
        }
    }
    echo $minCost . "\n";
}
main();
